// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(uint256(amount) > 0);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        vm.deal(address(this), 0);

        vm.prank(actor);
        c.withdrawBalance();

        assertTrue(c.getBalance(actor) == 0);
    }
}
